pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(this));
        // caller is not the owner (owner is unset => address(0)), so in P the call must revert
        vm.prank(caller);
        bool ok;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        // Rule: a non-owner cannot change ownership; owner stays address(0)
        assertTrue(ok ? false : c.owner() == address(0));
    }
}

