pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address other) public {
        // Keep the domain wide: any non-zero actor may become the owner,
        // `other` is an arbitrary unrelated address.
        vm.assume(actor != address(0));
        vm.assume(other != address(0));

        // Establish ownership: initially owner == address(0), which is the only
        // caller allowed by onlyOwner; use it to transfer ownership to `actor`.
        vm.prank(address(0));
        c.transferOwnership(actor);

        // Snapshot the owner before driving c through `owned`.
        address before = c.owner();

        // Drive c through `owned` from an arbitrary address `other` (fuzzed).
        // If `other` is not the owner the call must revert; if it is the owner
        // the call must complete WITHOUT changing the owner.
        vm.prank(other);
        try c.owned() {
            // Call succeeded: `other` was the owner (i.e. other == before).
            // Rule: owned() must not modify the owner state.
            assertTrue(c.owner() == before);
        } catch {
            // Call reverted (non-owner): the owner must still be unchanged.
            assertTrue(c.owner() == before);
        }
    }
}

