pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address newOwner) public {
        // Admissible domain: any caller, any proposed new owner (kept wide).
        // Establish a known owner via the legitimate ownership-transfer path.
        // At deployment owner() == address(0), so the zero address is the
        // legitimate current owner and may perform the transfer.
        vm.prank(address(0));
        c.transferOwnership(newOwner);

        // Track the owner solely through the public getter.
        address ownerBefore = c.owner();

        // Drive c through `owned` with the fuzzed caller; record success/revert.
        bool ok;
        vm.prank(caller);
        try c.owned() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: owned() is a no-op on ownership. For ANY caller it
        // either reverts (non-owner) or, if it succeeds, the owner state must
        // still equal the value established by transferOwnership — a call to
        // owned() must never change who owns the contract, regardless of who
        // called it. The mutant breaks this: its owned() body writes
        // owner = msg.sender, so whenever owned() succeeds the owner becomes
        // the caller rather than staying the transferred-to owner.
        bool ownerUnchangedByOwned = (!ok) || (c.owner() == ownerBefore);
        assertTrue(ownerUnchangedByOwned);
    }
}

