pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address firstOwner, address lastOwner) public {
        // The initial owner is address(0); use it to seed the contract with a fuzzed owner.
        vm.prank(address(0));
        c.transferOwnership(firstOwner);

        // Drive c through `owned` from an arbitrary fuzzed caller: in the reference this
        // either reverts (caller != owner) or leaves owner unchanged (caller == owner).
        vm.prank(caller);
        try c.owned() {
            // succeeded — in the reference, owner must still be firstOwner
            assertTrue(c.owner() == firstOwner, "owned() must not change owner");
            // Set the owner via the only sanctioned path; it must take effect exactly.
            vm.prank(firstOwner);
            c.transferOwnership(lastOwner);
            assertTrue(c.owner() == lastOwner, "owner must equal last value passed to transferOwnership");
        } catch {
            // reverted — owner must be untouched and equal to firstOwner
            assertTrue(c.owner() == firstOwner, "failed owned() call must not change owner");
        }
    }
}

